$js=<<<'JS'
<script>
const activityUrl='/plugins/demandas/front/time-entry-activities.php';
function h(v){const d=document.createElement('div');d.textContent=v;return d.innerHTML}
async function loadActivities(wpSelect,activitySelect,selected=''){const option=wpSelect.options[wpSelect.selectedIndex],wp=option?.dataset.wp||'',errorBox=activitySelect.parentElement?.querySelector('.te-activity-error');if(errorBox){errorBox.classList.add('d-none');errorBox.textContent=''}activitySelect.innerHTML='<option value="">Carregando...</option>';activitySelect.disabled=true;if(!wp){activitySelect.innerHTML='<option value="">Selecione primeiro a WP</option>';return}try{const response=await fetch(activityUrl+'?wp='+encodeURIComponent(wp));const data=await response.json();if(!data.ok)throw new Error(data.message||'Falha ao carregar atividades.');if(!data.activities.length)throw new Error('Nenhuma atividade de tempo está habilitada para o projeto desta Work Package.');activitySelect.innerHTML='<option value="">Selecione uma atividade</option>'+data.activities.map(a=>'<option value="'+h(a.href+'|'+a.name)+'" '+(a.href===selected?'selected':'')+'>'+h(a.name)+'</option>').join('');activitySelect.disabled=false}catch(error){activitySelect.innerHTML='<option value="">Atividades indisponíveis</option>';if(errorBox){errorBox.textContent=error.message;errorBox.classList.remove('d-none')}}}
const workPackageSearchUrl='/plugins/demandas/front/time-entry-work-packages.php';
function resetActivity(form){const activity=form.querySelector('.te-activity');activity.innerHTML='<option value="">Selecione primeiro a WP</option>';activity.disabled=true;}
function configureWorkPackageSource(form){const external=form.querySelector('.te-source-toggle:checked')?.value==='external';const linked=form.querySelector('.te-linked-source'),externalSource=form.querySelector('.te-external-source'),linkedSelect=form.querySelector('.te-linked-source .te-wp'),externalSelect=form.querySelector('.te-external-results');linked.classList.toggle('d-none',external);externalSource.classList.toggle('d-none',!external);linkedSelect.disabled=external;externalSelect.disabled=!external;if(external){linkedSelect.value='';externalSelect.value='';form.querySelector('.te-external-query').focus();}else{externalSelect.value='';}resetActivity(form);}
async function searchExternalWorkPackages(button){const form=button.closest('form'),query=form.querySelector('.te-external-query').value.trim(),results=form.querySelector('.te-external-results');if(query===''||(!/^\d+$/.test(query)&&query.length<3)){alert('Digite o número da Work Package ou ao menos 3 caracteres do título.');return;}button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Buscando';results.disabled=true;results.innerHTML='<option value="">Buscando no OpenProject...</option>';try{const response=await fetch(workPackageSearchUrl+'?query='+encodeURIComponent(query));const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Não foi possível consultar o OpenProject.');const workPackages=Array.isArray(data.work_packages)?data.work_packages:[];if(!workPackages.length){results.innerHTML='<option value="">Nenhuma Work Package encontrada</option>';return;}results.innerHTML='<option value="">Selecione uma Work Package</option>'+workPackages.map(wp=>{const detail=[wp.project,wp.type].filter(Boolean).join(' · ');return '<option value="0:'+Number(wp.id)+'" data-wp="'+Number(wp.id)+'">#'+Number(wp.id)+' · '+h(wp.subject||'Sem título')+(detail?' · '+h(detail):'')+'</option>';}).join('');results.disabled=false;}catch(error){results.innerHTML='<option value="">Pesquisa indisponível</option>';alert(error.message||'Não foi possível consultar o OpenProject.');}finally{button.disabled=false;button.innerHTML='<i class="ti ti-search me-1"></i>Buscar';}}
document.querySelectorAll('.te-source-toggle').forEach(input=>input.addEventListener('change',()=>configureWorkPackageSource(input.closest('form'))));
document.querySelectorAll('.te-external-search').forEach(button=>button.addEventListener('click',()=>searchExternalWorkPackages(button)));
document.querySelectorAll('.te-external-query').forEach(input=>input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();input.closest('.input-group').querySelector('.te-external-search').click();}}));
document.querySelectorAll('.te-source-toggle:checked').forEach(input=>configureWorkPackageSource(input.closest('form')));
document.querySelectorAll('.te-wp,.te-external-results').forEach(select=>select.addEventListener('change',()=>loadActivities(select,select.closest('form').querySelector('.te-activity'))));
document.querySelectorAll('.te-now').forEach(button=>button.onclick=()=>{const d=new Date();button.parentElement.querySelector('input').value=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')});
document.getElementById('te-all')?.addEventListener('change',event=>document.querySelectorAll('.te-select').forEach(c=>c.checked=event.target.checked));
const actionForm=document.getElementById('te-action-form');document.querySelectorAll('.te-action').forEach(button=>button.onclick=()=>{const action=button.dataset.action;if(action==='delete'&&!confirm('Excluir esta entrada de tempo? Se já estiver sincronizada, ela também será excluída do OpenProject.'))return;actionForm.elements.action.value=action;actionForm.elements.entry_id.value=button.dataset.id;actionForm.submit()});
document.querySelectorAll('.te-finish').forEach(button=>button.onclick=()=>{const endedAt=button.closest('.te-finish-group').querySelector('.te-inline-end').value;if(!endedAt){alert('Informe o horário de fim.');return}actionForm.elements.action.value='finish';actionForm.elements.entry_id.value=button.dataset.id;actionForm.elements.ended_at.value=endedAt;actionForm.submit()});
const editModal=new bootstrap.Modal(document.getElementById('teEdit'));document.querySelectorAll('.te-edit').forEach(button=>button.onclick=async()=>{const item=JSON.parse(button.dataset.entry),form=document.querySelector('#teEdit form');form.elements.entry_id.value=item.id;if(!item.ticketId&&!Array.from(form.elements.link.options).some(option=>option.value===item.link)){const option=new Option('#'+item.wp+' · Work Package sem chamado GLPI',item.link,true,true);option.dataset.wp=String(item.wp);form.elements.link.append(option);}form.elements.link.value=item.link;form.elements.spent_on.value=item.date;form.elements.started_at.value=item.start;form.elements.ended_at.value=item.end;form.elements.comment.value=item.comment;document.getElementById('te-edit-warning').classList.toggle('d-none',!item.synced);await loadActivities(form.elements.link,form.elements.activity,item.activity);editModal.show()});
const createElement=document.getElementById('teCreate'),createModal=new bootstrap.Modal(createElement),firstWp=createElement.querySelector('.te-wp');if(firstWp?.value){loadActivities(firstWp,firstWp.closest('form').querySelector('.te-activity'));createModal.show()}else if(new URLSearchParams(location.search).get('new')==='1')createModal.show();
</script>
